html:
{%- set rmh = (doc.relevant_medical_history or "") | lower -%}
{%- set rfr = (doc.reason_for_referral or "") | lower -%}
{%- set cond = doc.patient_condition_before_referral or "" -%}
{%- set prio = doc.referral_priority or "" -%}

<style>
  .rf { font-family: "Segoe UI", Arial, sans-serif; font-size: 11.5px; color: #000;
        border: 1.5px solid #000; padding: 14px 16px; line-height: 1.45; }
  .rf * { box-sizing: border-box; }
  .rf-head { display: flex; align-items: center; gap: 14px;
             border-bottom: 2px solid #000; padding-bottom: 8px; margin-bottom: 8px; }
  .rf-logo { width: 62px; height: auto; }
  .rf-title h1 { font-size: 21px; font-weight: 700; margin: 0; letter-spacing: .3px; }
  .rf-title h2 { font-size: 13.5px; font-weight: 700; margin: 2px 0 0; }
  .rf-sec { font-weight: 700; font-size: 12px; margin: 7px 0 2px; }
  .rf-row { margin: 1px 0; }
  .rf-lbl { font-weight: 700; }
  .val { display: inline-block; border-bottom: 1px solid #000; min-width: 90px;
         padding: 0 4px; font-weight: 400; }
  .val.w-lg { min-width: 300px; }
  .val.w-md { min-width: 175px; }
  .val.w-sm { min-width: 55px; }
  .rf table { width: 100%; border-collapse: collapse; margin-top: 3px; }
  .rf td { border: 1px solid #000; padding: 5px 6px; vertical-align: top; }
  .cell-h { font-weight: 700; display: block; margin-bottom: 3px; }
  .box-lg td { height: 118px; }
  .box-sm td { height: 132px; }
  .vitals { margin: 8px 0 4px; }
  .vitals span { margin-right: 26px; font-weight: 700; }
  .chk { display: block; padding-left: 34px; }
  .chk-inline { display: inline-block; margin-right: 26px; }
  .sign { margin-top: 18px; text-align: right; }
  .sign .rf-row { margin: 9px 0; }
  @media print { .rf { border-color: #000; } }
</style>

<div class="rf">

{{ letter_head }}

  <div class="rf-row">
    <span class="rf-lbl">Referral No.:</span> <span class="val w-md">{{ doc.name }}</span>
    <span class="rf-lbl">Date:</span> <span class="val w-sm">{{ frappe.utils.formatdate(doc.date, "dd / MM / yyyy") if doc.date else "" }}</span>
    <span class="rf-lbl">Time:</span> <span class="val w-sm">{{ doc.get_formatted("time") if doc.time else "" }}</span>
  </div>

  <div class="rf-sec">1. REFERRING FACILITY INFORMATION</div>
  <div class="rf-row">
    <span class="rf-lbl">Facility Name:</span> <span class="val w-lg"></span>
    <span class="rf-lbl">Contacts:</span> <span class="val w-md"></span>
  </div>
  <div class="rf-row"><span class="rf-lbl">Facility Type:</span> Community Clinic</div>
  <div class="rf-row">
    <span class="rf-lbl">Department/Unit:</span> <span class="val w-md"></span>
    <span class="rf-lbl">Referral Destination:</span> <span class="val w-md"></span>
  </div>

  <div class="rf-sec">2. PATIENT INFORMATION</div>
  <div class="rf-row">
    <span class="rf-lbl">Patient Name:</span> <span class="val w-lg">{{ doc.patient_name or "" }}</span>
    <span class="rf-lbl">Age:</span> <span class="val w-sm">{{ doc.age or "" }}</span>
    <span class="rf-lbl">Sex:</span>
    {{ "&#9746;" if doc.sex == "Male" else "&#9744;" }} Male
    {{ "&#9746;" if doc.sex == "Female" else "&#9744;" }} Female
  </div>
  <div class="rf-row">
    <span class="rf-lbl">Patient ID:</span> <span class="val w-sm">{{ doc.patient_id or "" }}</span>
    <span class="rf-lbl">Phone Number:</span> <span class="val w-md">{{ doc.mobile or "" }}</span>
    <span class="rf-lbl">Address/District:</span> <span class="val w-md">{{ doc.address or "" }}</span>
  </div>

  <div class="rf-sec">3. CLINICAL INFORMATION</div>
  <table class="box-lg">
    <tr>
      <td style="width:24%"><span class="cell-h">Presenting Complaint.</span>{{ doc.presenting_complaint or "" }}</td>
      <td style="width:26%"><span class="cell-h">History of Present Illness.</span>{{ doc.history_of_present_illness or "" }}</td>
      <td style="width:50%">
        <span class="cell-h">Relevant Medical History</span>
  
        <span class="chk">&#9744; Other: <span class="val w-md">{{ doc.relevant_medical_history or "" }}</span></span>
      </td>
    </tr>
  </table>

  <div class="rf-sec">4. CLINICAL ASSESSMENT</div>
  <div class="vitals">
    <span>BP: <span class="val w-sm">{{ doc.bp or "" }}</span> mmHg</span>
    <span>PR: <span class="val w-sm">{{ doc.pr or "" }}</span> b/m</span>
    <span>RR: <span class="val w-sm"></span> /min</span>
    <span>Temp: <span class="val w-sm">{{ doc.temp or "" }}</span> &deg;C</span>
    <span>O<sub>2</sub>: <span class="val w-sm">{{ doc.o2 or "" }}</span> %</span>
  </div>

  <table class="box-sm">
    <tr>
      <td style="width:28%"><span class="cell-h">Physical Examination / Clinical Findings.</span>{{ doc.physical_examination_clinical_findings or "" }}</td>
      <td style="width:24%"><span class="cell-h">Diagnosis</span>{{ doc.diagnosis or "" }}</td>
      <td style="width:24%"><span class="cell-h">Investigations.</span>{{ doc.investigations or "" }}</td>
      <td style="width:24%"><span class="cell-h">Treatment.</span>{{ doc.treatment or "" }}</td>
    </tr>
  </table>

  <div class="rf-sec">5. PATIENT CONDITION BEFORE REFERRAL</div>
  <div class="rf-row">
    <span class="chk-inline">{{ "&#9746;" if cond == "Stable" else "&#9744;" }} Stable</span>
    <span class="chk-inline">{{ "&#9746;" if cond == "Serious but Stable" else "&#9744;" }} Serious but Stable</span>
    <span class="chk-inline">{{ "&#9746;" if cond == "Unstable" else "&#9744;" }} Unstable</span>
    <span class="chk-inline">{{ "&#9746;" if cond in ["Critical", "Emergency"] else "&#9744;" }} Critical / Emergency</span>
  </div>

  <div class="rf-sec">6. REASON FOR REFERRAL</div>


  <span class="chk">&#9744; Other: <span class="val w-lg">{{ doc.reason_for_referral or "" }}</span></span>

  <div class="rf-sec">
    7. REFERRAL PRIORITY:
    <span class="chk-inline" style="font-weight:400; margin-left:10px;">{{ "&#9746;" if prio == "EMERGENCY" else "&#9744;" }} EMERGENCY</span>
    <span class="chk-inline" style="font-weight:400;">{{ "&#9746;" if prio == "URGENT" else "&#9744;" }} URGENT</span>
    <span class="chk-inline" style="font-weight:400;">{{ "&#9746;" if prio == "ROUTINE" else "&#9744;" }} ROUTINE</span>
  </div>

  <div class="sign">
    <div class="rf-row"><span class="rf-lbl">Doctor:</span> <span class="val w-md">{{ doc.doctor or "" }}</span></div>
    <div class="rf-row"><span class="rf-lbl">Signature:</span> <span class="val w-md"></span></div>
    <div class="rf-row"><span class="rf-lbl">Date:</span> <span class="val w-md">{{ frappe.utils.formatdate(doc.date, "dd / MM / yyyy") if doc.date else "" }}</span></div>
  </div>

</div>
